    'global.emails.user_data_collected_email_collector.body' => 'Cześć, <strong>{{NAME}}</strong>,<br /><br />Otrzymałeś właśnie nowe zgłoszenie danych z <strong>Email Collector</strong> od jednego z odwiedzających.<br /><br /><strong>E-mail:</strong> {{DATA_EMAIL}}<br /><strong>Imię i nazwisko:</strong> {{DATA_NAME}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Zobacz wszystkie zebrane dane</a><br /><br />Pozdrawiamy,<br />zespół {{WEBSITE_TITLE}}.',
    'global.emails.user_data_collected_contact_collector.body' => 'Cześć, <strong>{{NAME}}</strong>,<br /><br />Otrzymano nowe zgłoszenie z <strong>Formularza kontaktowego</strong> od jednego z odwiedzających Twoją stronę.<br /><br /><strong>E-mail:</strong> {{DATA_EMAIL}}<br /><strong>Telefon:</strong> {{DATA_PHONE}}<br /><strong>Imię i nazwisko:</strong> {{DATA_NAME}}<br /><strong>Wiadomość:</strong> {{DATA_MESSAGE}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Zobacz wszystkie zebrane dane</a><br /><br />Pozdrawiamy,<br />zespół {{WEBSITE_TITLE}}.',
    'global.emails.user_data_collected_appointment_calendar.body' => 'Cześć, <strong>{{NAME}}</strong>,<br /><br />Jeden z odwiedzających właśnie zarezerwował termin w Twoim <strong>Kalendarzu spotkań</strong>.<br /><br /><strong>Data:</strong> {{DATA_DATE}}<br /><strong>Godzina:</strong> {{DATA_TIME}}<br /><strong>Czas trwania:</strong> {{DATA_DURATION}}<br /><strong>E-mail:</strong> {{DATA_EMAIL}}<br /><strong>Telefon:</strong> {{DATA_PHONE}}<br /><strong>Imię i nazwisko:</strong> {{DATA_NAME}}<br /><strong>Wiadomość:</strong> {{DATA_MESSAGE}}<br /><br /><a href="{{DATA_LINK}}" class="cta">Zobacz wszystkie zebrane dane</a><br /><br />Pozdrawiamy,<br />zespół {{WEBSITE_TITLE}}.',
    'global.emails.user_guest_payment_donation.subject' => 'Darowizna w wysokości {{TOTAL_AMOUNT}} {{CURRENCY}} na rzecz „{{DONATION_TITLE}}”: {{WEBSITE_TITLE}}',
    'global.emails.user_guest_payment_donation.body' => 'Witaj, <strong>{{NAME}}</strong>,<br /><br />Otrzymujesz właśnie nową darowiznę od jednego z odwiedzających Twoją stronę.<br /><br /><strong>E-mail:</strong> {{EMAIL}}<br /><strong>Imię i nazwisko:</strong> {{PAYER_NAME}}<br /><strong>Łączna kwota:</strong> {{TOTAL_AMOUNT}}<br /><strong>Waluta:</strong> {{CURRENCY}}<br /><strong>Operator płatności:</strong> {{PROCESSOR}}<br /><strong>Darowizna:</strong> {{DONATION_TITLE}}<br /><strong>Wiadomość:</strong> {{MESSAGE}}<br /><br /><a href="{{GUEST_PAYMENT_LINK}}" class="cta">Zobacz płatność</a><br /><br />Pozdrawiamy,<br />Zespół {{WEBSITE_TITLE}}.',
