    'global.emails.user_guest_payment_service.body' => 'Cześć, <strong>{{NAME}}</strong>,<br /><br />Otrzymujesz właśnie nową płatność od jednego z odwiedzających za jedną ze swoich usług.<br /><br /><strong>E-mail:</strong> {{EMAIL}}<br /><strong>Imię i nazwisko:</strong> {{PAYER_NAME}}<br /><strong>Łączna kwota:</strong> {{TOTAL_AMOUNT}}<br /><strong>Waluta:</strong> {{CURRENCY}}<br /><strong>Operator płatności:</strong> {{PROCESSOR}}<br /><strong>Usługa:</strong> {{SERVICE_TITLE}}<br /><strong>Wiadomość:</strong> {{MESSAGE}}<br /><br /><a href="{{GUEST_PAYMENT_LINK}}" class="cta">Zobacz płatność</a><br /><br />Pozdrawiamy,<br />Zespół {{WEBSITE_TITLE}}.',
