    'global.emails.guest_guest_payment_service.body' => 'Witaj, <strong>{{NAME}}</strong>,<br /><br />To oficjalne powiadomienie e-mail potwierdzające, że Twoje zamówienie zostało przyjęte. Usługodawca skontaktuje się z Tobą tak szybko, jak to możliwe.<br /><br />Pozdrawiamy,<br />zespół {{WEBSITE_TITLE}}.',
    'global.emails.user_plan_expiry_reminder.subject' => 'Twój plan wygaśnie za {{DAYS_UNTIL_EXPIRATION}} dni: {{WEBSITE_TITLE}}',
