    'global.emails.user_plan_expired.subject' => 'Twój plan wygasł: {{WEBSITE_TITLE}}',
    'global.emails.user_plan_expired.body' => 'Witaj, <strong>{{NAME}}</strong>,<br /><br />Twój <strong>plan {{PLAN_NAME}}</strong> wygasł, ponieważ nie odnowiłeś(-aś) członkostwa.<br /><br />Jeśli chcesz nadal korzystać z naszej witryny ze wszystkimi dotychczasowymi funkcjami, musisz odnowić członkostwo.<br /><br /><a href="{{USER_PLAN_RENEW_LINK}}" class="cta">Odnów plan</a><br /><br />Pozdrawiamy,<br />zespół {{WEBSITE_TITLE}}.',
