    'dashboard.onboarding_modal.step_1_title' => '1. Pulpit nawigacyjny jako punkt wyjścia',
    'dashboard.onboarding_modal.step_1_text' => 'Pulpit to główne miejsce, w którym możesz poznać system FCC. Znajdziesz tu informacje o swojej aktywności, materiały edukacyjne, kolejne działania i podsumowanie tego, co już przynosi rezultaty.',
    'dashboard.onboarding_modal.step_2_title' => '2. Główne menu i treści',
    'dashboard.onboarding_modal.step_2_text' => 'Menu główne daje dostęp do treści Forever Card Club, produktów Forever, bloga, kontaktu i panelu. Tędy przechodzisz, aby się uczyć, udostępniać treści i rozwijać swój biznes Forever.',
    'dashboard.onboarding_modal.step_3_title' => '3. Aplikacje i linki FCC',
    'dashboard.onboarding_modal.step_3_text' => 'Twoje aplikacje FCC to twoja osobista baza cyfrowa, która pomaga kierować odwiedzających do produktów, rejestracji, kontaktów i innych ważnych działań.',
    'dashboard.onboarding_modal.step_4_title' => '4. Blog i rekomendacje',
    'dashboard.onboarding_modal.step_4_text' => 'Blog i sekcja Forever Products służą do udostępniania treści edukacyjnych i produktowych wraz z Twoją rekomendacją, dzięki czemu zainteresowanie produktami i sklepem internetowym pozostaje powiązane z Tobą.',
    'dashboard.onboarding_modal.step_5_title' => '5. Sygnały, AI i Twój plan rozwoju',
    'dashboard.onboarding_modal.step_5_text' => 'FCC śledzi, które działania rzeczywiście prowadzą do sklepu internetowego Forever, a AI wykorzystuje te informacje, aby sugerować jaśniejsze kolejne kroki i lepszy plan rozwoju.',
    'dashboard.onboarding_modal.step_6_title' => '6. Wsparcie, edukacja i tematy webinarów',
    'dashboard.onboarding_modal.step_6_text' => 'Gdy napotykasz trudności lub szukasz nowego kierunku, wsparcie i tematy webinarów zapewniają dodatkowe wyjaśnienia, pomoc oraz możliwość zasugerowania tego, co będzie najważniejsze na kolejnym etapie Twojego rozwoju.',
    'dashboard.onboarding_modal.primary' => 'Rozpocznij samouczek',
    'dashboard.onboarding_modal.secondary' => 'Po prostu pokaż mi, jak to działa',
    'dashboard.tutorials.eyebrow' => 'Szybkie poradniki',
    'dashboard.tutorials.title' => 'Poradniki dotyczące twoich pierwszych rekomendacji',
    'dashboard.tutorials.text' => 'Otwórz krótkie poradniki dotyczące konkretnych działań, które pomogą ci zwiększyć zainteresowanie, liczbę kliknięć i poleceń za pomocą systemu FCC.',
    'dashboard.tutorials.blog_referral.badge' => 'Blog FCC i rekomendacja',
    'dashboard.tutorials.blog_referral.title' => 'Udostępnij artykuł ze swoim linkiem rekomendacyjnym',
    'dashboard.tutorials.blog_referral.text' => 'Ten przewodnik przeprowadzi cię od sekcji Forever Products do gotowego linku, który automatycznie połączy twoje treści, rekomendację i wizytę w sklepie internetowym.',
    'dashboard.tutorials.blog_referral.button' => 'Przewodnik Start',
    'dashboard.tutorials.blog_referral.modal_title' => 'Jak udostępnić artykuł za pomocą własnego linku polecającego',
    'dashboard.tutorials.blog_referral.modal_subtitle' => 'Od otwarcia sekcji Forever Products do skopiowania gotowego linku zawierającego już twoją rekomendację.',
    'dashboard.tutorials.blog_referral.modal_callout' => 'Gdy udostępniasz artykuł w ten sposób, FCC automatycznie dodaje Twoją rekomendację do wysyłanego linku. To najprostszy sposób, aby treść o produkcie od razu wspierała Twój przekaz i rekomendację.',
    'dashboard.tutorials.blog_referral.modal_primary' => 'Rozpocznij przewodnik krok po kroku',
    'dashboard.tutorials.blog_referral.next_open_article' => 'Otwórz artykuł',
    'dashboard.tutorials.blog_referral.step_1_title' => '1. Kliknij Forever Products',
    'dashboard.tutorials.blog_referral.step_1_text' => 'Otwórz sekcję Forever Products w menu po lewej stronie. Przejdziesz do bloga z treściami o produktach gotowymi do udostępnienia.',
    'dashboard.tutorials.blog_referral.step_2_title' => '2. Wybierz produkt lub znajdź go za pomocą wyszukiwarki',
    'dashboard.tutorials.blog_referral.step_2_text' => 'Na blogu wybierz produkt, który chcesz polecić. Jeśli chcesz szybciej znaleźć odpowiedni artykuł, skorzystaj z wyszukiwarki i otwórz produkt odpowiadający zainteresowaniom tej osoby.',
    'dashboard.tutorials.blog_referral.step_3_title' => '3. Skorzystaj z sekcji udostępniania z rekomendacją',
    'dashboard.tutorials.blog_referral.step_3_text' => 'Na górze artykułu znajdziesz sekcję „Udostępnij tę stronę wraz z rekomendacją”. Możesz tam skopiować link lub od razu udostępnić stronę za pomocą dostępnych przycisków.',
    'dashboard.tutorials.blog_referral.step_4_title' => '4. Link zawiera już twoją rekomendację',
    'dashboard.tutorials.blog_referral.step_4_text' => 'Link, który kopiujesz lub udostępniasz, zawiera już Twój unikalny link polecający. Jeśli ktoś otworzy za jego pośrednictwem sklep internetowy Forever, ta wizyta i rekomendacja zostaną powiązane z Twoim kontem.',
    'dashboard.tutorials.blog_referral.step_5_title' => 'Dlaczego to ważne',
    'dashboard.tutorials.blog_referral.step_5_text' => 'Te kliknięcia wzmacniają sygnał sprzedażowy, pomagają pozycjonować aplikację Forever Card i tworzą przejrzystą ścieżkę zainteresowania produktami Forever Living Products.',
    'dashboard.tutorials.blog_referral.category_step_1_title' => 'Jesteś teraz w sekcji Produkty Forever',
    'dashboard.tutorials.blog_referral.category_step_1_text' => 'To sekcja bloga o produktach, zawierająca treści, które możesz udostępniać, polecając produkty. Przewodnik prowadzi teraz do odpowiedniego artykułu i linku z poleceniem, które możesz udostępnić.',
    'dashboard.tutorials.blog_referral.category_step_2_title' => 'Znajdź produkt, który chcesz polecić',
    'dashboard.tutorials.blog_referral.category_step_2_text' => 'Jeśli już wiesz, który produkt chcesz wysłać, wpisz jego nazwę w wyszukiwarce. To najszybszy sposób, by znaleźć artykuł odpowiadający zainteresowaniom danej osoby.',
    'dashboard.tutorials.blog_referral.category_step_3_title' => 'Otwórz artykuł o produkcie',
    'dashboard.tutorials.blog_referral.category_step_3_text' => 'W tym przewodniku otworzymy pierwszy widoczny artykuł. W artykule przewodnik będzie kontynuowany i pokaże ci, gdzie skopiować lub udostępnić swój link polecający.',
    'dashboard.tutorials.blog_referral.article_step_1_title' => 'Tutaj generowany jest link rekomendacyjny',
    'dashboard.tutorials.blog_referral.article_step_1_text' => 'U góry artykułu znajduje się pasek udostępniania z twoją rekomendacją. Gdy udostępniasz artykuł z tego miejsca, FCC dodaje do linku twoją osobistą rekomendację.',
    'dashboard.tutorials.blog_referral.article_step_2_title' => 'Sprawdź, jak działa system',
    'dashboard.tutorials.blog_referral.article_step_2_text' => 'Kliknięcie opcji Jak to działa otwiera krótkie wyjaśnienie, że twoja rekomendacja zostaje dodana automatycznie, a odwiedziny pozostają powiązane z twoim kontem.',
    'dashboard.tutorials.blog_referral.article_step_3_title' => 'Udostępnij artykuł za pomocą gotowych przycisków',
    'dashboard.tutorials.blog_referral.article_step_3_text' => 'Tutaj możesz od razu udostępnić artykuł w mediach społecznościowych lub wysłać go w wiadomości. Wszystkie opcje korzystają z tego samego linku zawierającego Twoją rekomendację.',
    'dashboard.tutorials.blog_referral.article_step_4_title' => 'Skopiuj gotowy link',
    'dashboard.tutorials.blog_referral.article_step_4_text' => 'Jeśli chcesz ręcznie wkleić link do wiadomości, relacji lub posta, skopiuj go tutaj. Osoba, która przejdzie przez ten link do sklepu internetowego Forever, pozostanie przypisana do Twojej rekomendacji.',
    'dashboard.tour.launch' => 'Rozpocznij samouczek',
    'dashboard.tour.replay' => 'Odtwórz samouczek',
