    'dashboard.tour.step_guide_title' => 'Przewodnik po tej stronie',
    'dashboard.tour.step_guide_text' => 'Na każdej ważnej stronie FCC przewodnik znajduje się w prawym górnym rogu. Kliknij ten przycisk, gdy chcesz skorzystać z krótkiej instrukcji krok po kroku dotyczącej aktualnie wyświetlanej strony.',
    'dashboard.tour.step_sidebar_title' => 'Menu FCC i obszary robocze',
    'dashboard.tour.step_sidebar_text' => 'To główne menu FCC w twoim systemie użytkownika. Stąd otworzysz pulpit, aplikacje, plan rozwoju, wyniki, materiały edukacyjne i treści o produktach, które wspierają twoją codzienną działalność Forever.',
    'dashboard.tour.step_menu_apps_title' => 'aplikacje FCC',
    'dashboard.tour.step_menu_apps_text' => 'Tutaj otwierasz swoje aplikacje Forever Card. To twoja osobista cyfrowa baza, która pomaga kierować odwiedzających do produktów, rejestracji, kontaktów i innych ważnych działań.',
    'dashboard.tour.step_menu_ai_plan_title' => 'Plan rozwoju AI',
    'dashboard.tour.step_menu_ai_plan_text' => 'Tutaj otwierasz swój plan rozwoju i realizujesz go. AI analizuje dane z twoich aplikacji, treści na blogu i kliknięcia w sklepie internetowym, aby podpowiedzieć najlepsze kolejne działania na najbliższe dni.',
    'dashboard.tour.step_menu_results_title' => 'Wyniki FCC',
    'dashboard.tour.step_menu_results_text' => 'Tutaj możesz sprawdzić, czy twój system rzeczywiście przynosi efekty. Ta sekcja pomaga śledzić kliknięcia, postępy i sygnały wskazujące, co warto rozwijać.',
    'dashboard.tour.step_menu_education_title' => 'Szkolenia Forever',
    'dashboard.tour.step_menu_education_text' => 'W tej sekcji znajdziesz materiały szkoleniowe wideo i objaśnienia, które pomogą Ci zrozumieć system, przejść przez kolejne kroki i wykorzystać zdobytą wiedzę w codziennej pracy.',
    'dashboard.tour.step_menu_products_title' => 'Produkty Forever',
    'dashboard.tour.step_menu_products_text' => 'Otwierają artykuły o produktach i treści z rekomendacjami. To jedno z głównych miejsc, z których udostępniasz treści, aby przedstawić swoją rekomendację i skierować zainteresowane osoby do sklepu internetowego Forever.',
    'dashboard.tour.step_navbar_title' => 'Główne menu FCC',
    'dashboard.tour.step_navbar_text' => 'Menu u góry to główna nawigacja po szkoleniach, produktach, treściach blogowych i kontaktach, a także sposób powrotu do pulpitu. To tutaj zaczyna się poznawanie całego systemu FCC.',
    'dashboard.tour.step_menu_forever_club_title' => 'Forever Card Club',
    'dashboard.tour.step_menu_forever_club_text' => 'Otwiera główne informacje FCC, objaśnienia systemu oraz treści, które pomagają zrozumieć, jak aplikacje, rekomendacje i narzędzia współdziałają, wspierając rozwój biznesu Forever.',
    'dashboard.tour.step_menu_forever_products_title' => 'Produkty Forever',
    'dashboard.tour.step_menu_forever_products_text' => 'Otwiera treści o produktach i artykuły, którymi możesz się podzielić, polecając produkty. To ważny element wzbudzania zainteresowania i kierowania odwiedzających do sklepu internetowego Forever.',
    'dashboard.tour.step_menu_blog_title' => 'Blog',
    'dashboard.tour.step_menu_blog_text' => 'Blog oferuje szersze treści edukacyjne i biznesowe, które możesz wykorzystać we wpisach, wiadomościach i budowaniu zaufania poprzez wartościowe treści, a nie tylko bezpośrednią sprzedaż.',
    'dashboard.tour.step_menu_contact_title' => 'Kontakt',
    'dashboard.tour.step_menu_contact_text' => 'Tutaj możesz skontaktować się z innymi i uzyskać wsparcie w razie dodatkowych pytań. Jeśli coś jest niejasne lub potrzebujesz wskazówek, możesz poprosić o pomoc właśnie tutaj.',
    'dashboard.tour.step_menu_dashboard_title' => 'Przejdź do panelu',
    'dashboard.tour.step_menu_dashboard_text' => 'Panel to twoje centrum dowodzenia. Śledzisz tu swoje sygnały, uczysz się z poradników, sprawdzasz, co działa, i decydujesz, jaki będzie twój następny krok.',
    'dashboard.tour.step_hero_title' => 'Strona główna Twojej działalności FCC',
    'dashboard.tour.step_hero_text' => 'Ta sekcja podsumowuje, na jakim etapie jesteś, na czym się koncentrujesz i które ścieżki najszybciej prowadzą do aplikacji, wsparcia i materiałów edukacyjnych.',
    'dashboard.tour.step_growth_title' => 'Sygnały i odblokowania',
    'dashboard.tour.step_growth_text' => 'Tutaj możesz sprawdzić, jak aktywność przekłada się na przejścia do sklepu internetowego Forever za pośrednictwem aplikacji FCC, bloga i innych narzędzi. Ten sygnał pomaga określić tempo wsparcia AI i odblokowywania kolejnych elementów planu rozwoju.',
    'dashboard.tour.step_tutorials_title' => 'Krótkie poradniki i materiały edukacyjne',
    'dashboard.tour.step_tutorials_text' => 'Tutaj znajdziesz krótkie, praktyczne poradniki dotyczące konkretnych działań. Tak w praktyce wygląda edukacja FCC: nie tylko teoria, ale też małe kroki, które możesz zastosować od razu.',
    'dashboard.tour.step_workbench_title' => 'Workbench',
    'dashboard.tour.step_workbench_text' => 'Od razu widzisz, co działa, gdzie wynik spada i które części systemu już przyciągają zainteresowanie. Dzięki temu możesz podejmować decyzje na podstawie rzeczywistych sygnałów, a nie domysłów.',
    'dashboard.tour.step_chart_title' => 'Kliknięcia, które przynoszą rezultaty',
    'dashboard.tour.step_chart_text' => 'Wykres rozdziela dane z aplikacji → Forever, bloga → Forever, rejestracje i kontakty od danych z lejka i czatu AI, dzięki czemu wyraźnie widać, która część systemu przynosi rzeczywiste efekty biznesowe.',
    'dashboard.tour.step_next_action_title' => 'Twój następny krok',
    'dashboard.tour.step_next_action_text' => 'Ten blok zawiera jedną jasną rekomendację dotyczącą tego, co zrobić teraz. Celem FCC nie jest zasypywanie Cię danymi, lecz pomoc w wyborze najbardziej przydatnego kolejnego kroku.',
    'dashboard.tour.step_support_title' => 'Tematy wsparcia i webinarów',
    'dashboard.tour.step_support_text' => 'Tutaj możesz skontaktować się z pomocą techniczną, przeczytać odpowiedzi administratorów i zaproponować tematy webinarów, które mamy omówić. To część edukacyjna FCC, która pomaga, gdy napotkasz trudności lub chcesz lepiej zrozumieć temat.',
