    'fcc_results.homepage_spotlight_notice_after' => 'Na stronie widzisz publiczne aplikacje główne, które w ciągu 30 dni osiągnęły 15+. Gdy współpracownik osiągnie 50+ w ciągu 30 dni, trafia do mocniejszego kręgu sponsorów polecanych na stronie głównej, pod warunkiem że wyświetlanie publiczne jest włączone i zatwierdzone przez administratora.',
    'fcc_results.proof_note' => 'Wyniki FCC pokazują wskaźniki aktywności. Wyróżnione aplikacje to publiczne przykłady obejmujące co najmniej 15 wizyt w ciągu 30 dni, a co najmniej 50 wizyt w ciągu 30 dni dodatkowo wzmacnia pozycję na drodze do rekomendacji sponsorów na stronie głównej.',
    'fcc_results.metrics_note' => 'Progi i rankingi uwzględniają kwalifikujące się wizyty w Forever, pochodzące ze zwykłych i dedykowanych przycisków oraz blogów, z zabezpieczeniem przed wielokrotnym naliczaniem. Sam tag UTM nie daje punktu. Wkład w kwalifikację do lejka VIP jest wyświetlany osobno. Inne lejki i kontakty z czatu AI wskazują na zainteresowanie.',
