    'fcc_results.tips.title' => 'Jak osiągnąć kolejny poziom',
    'fcc_results.tips.subheader' => 'Wykonaj w tym tygodniu 1–2 drobne działania, aby zwiększyć swoje szanse na wejście na listę lub awans na niej.',
