    'fcc_results.tips.item_2' => 'Wyślij swoją aplikację Forever Card obecnym klientom, aby mogli skorzystać z niej przy kolejnym zamówieniu.',
    'fcc_results.tips.item_3' => 'Przenieś blok sklepu internetowego wyżej w aplikacji, aby był od razu widoczny.',
    'fcc_results.tips.item_4' => 'Dodaj krótką frazę nad przyciskiem sklepu internetowego, np. „Zobacz produkty, które polecam”.',
    'fcc_results.tips.item_5' => 'Podczas rozmów ze znajomymi używaj fizycznej karty NFC, aby jednym szybkim dotknięciem pokazać polecane produkty.',
    'fcc_results.tips.item_6' => 'Udostępnij produkt z bloga w relacji za pomocą linku do udostępniania albo wyślij go bezpośrednio zainteresowanym osobom w wiadomości, aby zwiększyć liczbę wizyt w Forever Shop dzięki Twojej rekomendacji.',
    'fcc_results.tips.item_7' => 'Aktywuj doradcę AI w aplikacji i zachęcaj odwiedzających do rozmowy, ponieważ kontakty zebrane przez AI również wliczają się do Twojego wyniku kontaktów.',
    'fcc_results.challenge.title' => 'Cotygodniowe wyzwanie',
