    'fcc_results.ai_widget.active_benefits' => 'Po osiągnięciu poziomu 15 odblokujesz w planie rozwoju bardziej zaawansowany rytm pracy z AI: aktywny plan tygodniowy i regularny przegląd aplikacji z AI.',
    'fcc_results.ai_widget.vip_benefits' => 'Przy 50 przechodzisz na wyższy poziom statusu na stronie głównej i w sekcji polecanych sponsorów. W FCC jest to oznaka ciągłości i doświadczenia.',
    'fcc_results.ai_widget.pro_note' => 'Twój plan rozwoju i FCC Results korzystają z tego samego sygnału kwalifikacyjnego dla progów 15+ i 50+. Kontakty przez WhatsApp i czat AI dostarczają dodatkowego kontekstu dotyczącego zainteresowania, ale nie dodają punktów do tych progów.',
    'fcc_results.ai_widget.pro_required_note' => 'Aby odblokować pełny proces AI w ramach Twojego planu rozwoju, potrzebujesz aktywnego pakietu Pro. Tutaj nadal widzisz postępy dotyczące twojego zakwalifikowanego sygnału.',
    'fcc_results.ai_widget.featured_note_7d' => 'Wynik 15+ w ciągu 30 dni umieszcza Cię na liście polecanych aplikacji, a 50+ w ciągu 30 dni przybliża Cię do grona sponsorów polecanych na stronie głównej. Ten widok z 7 dni służy wyłącznie do sprawdzenia tygodniowego rytmu.',
    'fcc_results.ai_widget.featured_note_7d_unlocked' => 'Masz już 50+ w 30 dni i jesteś w silniejszej, zalecanej strefie sponsorskiej. Jeśli utrzymasz też 15+ w 7 dni, potwierdzisz stabilny rytm tygodniowy.',
    'fcc_results.ai_widget.featured_note_7d_experience' => 'Masz co najmniej 50 w ciągu 30 dni i potwierdzone co najmniej 15 w ciągu 7 dni. To mocny sygnał dla osób szukających polecanych sponsorów oraz potwierdzenie stabilnego tygodniowego rytmu.',
