    'ai_plan.phase_2_text' => 'Krótka cotygodniowa ankieta i logika odblokowywania dostępu dla współpracowników, którzy mają wystarczająco dużo danych.',
    'ai_plan.phase_3_title' => 'Pytania dopasowujące i plan tygodniowy',
    'ai_plan.phase_3_text' => 'Pytania dostosowują się do analityki i zmian, a AI przygotowuje konkretny plan działania na 7 dni.',
    'ai_plan.phase_4_title' => 'Coaching administratora i porównanie okresów',
    'ai_plan.phase_4_text' => 'Administrator widzi zmiany w czasie, notatkę mentora AI i priorytet coachingowy dla każdego współpracownika.',
    'ai_plan.weekly_title' => 'Cotygodniowa rozmowa kontrolna',
    'ai_plan.weekly_text' => 'Ta krótka odprawa jest dostępna raz na 7 dni dla współpracowników, w przypadku których jest wystarczająco dużo sygnałów. Na tym etapie zapisujemy kontekst tygodnia i przygotowujemy system do tygodniowego planu w fazie 3.',
    'ai_plan.weekly_cycle_title' => 'Tygodniowy cykl krok po kroku',
    'ai_plan.weekly_cycle_text' => 'Spokojnie trzymaj się tej kolejności: najpierw krótka rozmowa kontrolna, potem plan na 7 dni, a na końcu omówienie wyników i wyższy poziom na kolejną rundę.',
    'ai_plan.weekly_cycle_next_label' => 'Zrób to teraz',
    'ai_plan.weekly_cycle_step_1_title' => 'Uzupełnij cotygodniowe podsumowanie',
    'ai_plan.weekly_cycle_step_1_text' => 'Tutaj AI poznaje twoje rzeczywiste priorytety, poziom energii i sytuację w tym tygodniu.',
    'ai_plan.weekly_cycle_step_2_title' => 'Postępuj zgodnie z 7-dniowym planem',
    'ai_plan.weekly_cycle_step_2_text' => 'Po zapisaniu podsumowania otrzymasz jasny plan działania na cały tydzień.',
    'ai_plan.weekly_cycle_step_3_title' => 'Zapisz wynik i rozwijaj się dalej',
    'ai_plan.weekly_cycle_step_3_text' => 'Na koniec krótko zapisz, co się sprawdziło i co chcesz teraz poprawić.',
    'ai_plan.weekly_cycle_next_fill' => 'Wypełnij cotygodniową ankietę i wykorzystaj ją do rozpoczęcia nowego 7-dniowego planu.',
    'ai_plan.weekly_cycle_next_wait_plan' => 'Cotygodniowe zameldowanie zostało zapisane. Otwórz plan, gdy tylko będzie gotowy.',
    'ai_plan.weekly_cycle_next_record' => 'Realizuj plan przez cały tydzień, a potem zapisz wynik i kolejną rzecz do poprawy.',
    'ai_plan.weekly_cycle_next_done' => 'Ten cykl jest zamknięty. Gdy otworzy się kolejne miejsce, rozpoczniesz następną rundę.',
