    'ai_plan.weekly_context' => 'Co AI powinno wiedzieć o tym tygodniu?',
    'ai_plan.weekly_context_placeholder' => 'Przykład: W ten weekend mam wydarzenie, w tym tygodniu nie chcę publikować rolek i chcę skupić się tylko na relacjach oraz kontakcie z osobami, które już zareagowały.',
    'ai_plan.weekly_save' => 'Zapisz cotygodniowe podsumowanie',
    'ai_plan.weekly_footer' => 'Faza 2 zapisuje cotygodniowy stan i dodaje rytm raz na 7 dni. Plan pojawia się w fazie 3.',
    'ai_plan.weekly_footer_phase_3' => 'Ta cotygodniowa odprawa od razu zasila plan na 7 dni, dlatego dodatkowa odpowiedź powinna być jak najbardziej konkretna.',
    'ai_plan.weekly_empty' => 'Nie zapisano jeszcze żadnego cotygodniowego podsumowania.',
    'ai_plan.weekly_next' => 'Następna cotygodniowa kontrola',
    'ai_plan.weekly_now' => 'Dostępne teraz',
    'ai_plan.weekly_success_message' => 'Zapisano cotygodniowe podsumowanie. Następne będzie dostępne za 7 dni.',
    'ai_plan.weekly_success_message_phase_3' => 'Zapisano cotygodniowe podsumowanie i wygenerowano plan na 7 dni.',
    'ai_plan.weekly_fallback_message' => 'Przetwarzanie AI utknęło, dlatego od razu zapisaliśmy bezpieczną wersję planu awaryjnego. Możesz z niej skorzystać od razu, a kolejna aktualizacja będzie ją normalnie kontynuować.',
    'ai_plan.preferences_persist_failed_message' => 'Plan został wygenerowany, ale nie udało się go poprawnie zapisać. Odśwież stronę i spróbuj ponownie. Jeśli problem się powtórzy, prawdopodobną przyczyną jest zbyt obszerna historia AI, którą nowa aktualizacja automatycznie skróci.',
    'ai_plan.app_review_persist_failed_message' => 'Analiza AI w aplikacji została wygenerowana, ale nie udało się jej poprawnie zapisać. Odśwież stronę i spróbuj ponownie. Jeśli problem się powtórzy, system automatycznie usunie starsze wpisy z historii AI, aby można było zapisać nową analizę.',
    'ai_plan.weekly_adaptive_title' => 'Pytanie adaptacyjne',
    'ai_plan.weekly_locked_profile_title' => 'Najpierw uzupełnij podstawowy profil',
    'ai_plan.weekly_locked_profile' => 'Przed cotygodniowym sprawdzeniem postępów uzupełnij podstawowy profil AI z pierwszego etapu, aby system poznał Twój cel, odbiorców i styl pracy.',
    'ai_plan.weekly_locked_signal_title' => 'Cotygodniowe odblokowanie nie jest jeszcze dostępne',
    'ai_plan.weekly_locked_signal' => 'Aby odbyć cotygodniowe spotkanie kontrolne, w ciągu ostatnich 30 dni musisz uzyskać co najmniej %s kliknięć, rejestracji i kontaktów przez czat AI. Wliczają się w to kliknięcia Forever, rejestracje przez lejek, kontakty przez czat AI i kliknięcia WhatsApp. Obecnie masz ich %s.',
    'ai_plan.weekly_locked_pro' => 'Tygodniowy plan AI jest dostępny tylko dla aktywnych użytkowników PRO.',
    'ai_plan.weekly_locked_cooldown_title' => 'Możliwość zameldowania jest tymczasowo zablokowana',
    'ai_plan.weekly_locked_cooldown' => 'Nowe cotygodniowe podsumowanie możesz otworzyć po %s.',
    'ai_plan.weekly_locked_cooldown_short' => 'Następna konsultacja będzie dostępna za około %s dni.',
    'ai_plan.why_title' => 'Dlaczego to działa w ten sposób',
    'ai_plan.why_text' => 'Analityka pokazuje, co się wydarzyło, ale nie dlaczego. Ten profil uzupełnia ją o informacje, które zna tylko współpracownik: cel, odbiorców, możliwości, styl i ograniczenia. Po połączeniu obu źródeł AI może tworzyć użyteczne i konkretne rekomendacje zamiast ogólnikowych porad.',
    'ai_plan.analytics_title' => 'Co pokazują obecne dane',
    'ai_plan.analytics_top_source' => 'Skąd najczęściej pochodzą ludzie',
