    'ai_plan.analytics_step_objective.forever_shop' => 'Kliknij, aby przejść do Forever Shop lub ścieżki zamawiania bez rejestracji',
    'ai_plan.signal_summary.title' => 'Co to oznacza teraz',
    'ai_plan.signal_summary.signal_label' => 'Bieżący sygnał',
    'ai_plan.signal_summary.signal_text_default' => 'Widać pewien sygnał, ale nie jest on jeszcze na tyle silny, by zapewnić stabilny wynik bez lepszego skupienia.',
    'ai_plan.signal_summary.signal_text_zero' => 'Nie ma jeszcze rzeczywistych danych o aktywności w Forever Webshop. Pierwszym celem nie jest zwiększanie złożoności, lecz uzyskanie pierwszych wartościowych kliknięć, które mają sens.',
    'ai_plan.signal_summary.signal_text_building' => 'W ciągu ostatnich 30 dni Twoje linki do Forever Webshop uzyskały %s kliknięć. Potrzebujesz co najmniej %s, aby tygodniowy plan opierał się na rzeczywistych sygnałach, a nie na przypuszczeniach.',
    'ai_plan.signal_summary.signal_text_ready' => 'W ciągu ostatnich 30 dni odnotowano %s kliknięć w Forever Webshop. Oznacza to, że system może teraz przygotować tygodniowy plan na podstawie rzeczywistych zachowań odwiedzających.',
    'ai_plan.signal_summary.action_label' => 'Najbardziej przydatne działanie na teraz',
    'ai_plan.signal_summary.action_text_default' => 'Skup się na jednym konkretnym celu: jednym jasnym przekazie, jednym głównym kierunku i jednej aplikacji, z której naprawdę skorzystasz w tym tygodniu.',
    'ai_plan.signal_summary.action_text_direct' => 'Źródło wizyty jest zbyt często niejasne. W tym tygodniu nie rozpraszaj swoich działań. Korzystaj z jednego powtarzalnego formatu i jednej jasnej ścieżki do Forever Shop.',
    'ai_plan.signal_summary.action_text_recruitment' => 'Jeśli skupiasz się na biznesie, przedstaw jedną konkretną historię i zaproś do rozmowy w tym tygodniu, zamiast naraz zasypywać kogoś wieloma wiadomościami i ofertami.',
    'ai_plan.signal_summary.action_text_building' => 'Najważniejsze jest pozyskanie pierwszych wartościowych kliknięć w Forever Webshop dzięki jednej powtarzalnej aktywności, zamiast rozpoczynania kilku działań jednocześnie.',
    'ai_plan.signal_summary.action_text_funnel_live' => 'Obecnie aktywnych jest %s z %s etapów sprzedaży. W tym tygodniu skup się na tym, by ścieżka była przejrzysta i nie wymagała od odwiedzającego wybierania zbyt wielu rzeczy naraz.',
    'ai_plan.signal_summary.action_text_sales_ready' => 'Dane są wystarczająco wyraźne, by w tym tygodniu skupić się na przekuciu zainteresowania w działania w sklepie internetowym, a nie tylko na zwiększaniu liczby odwiedzin.',
    'ai_plan.signal_summary.action_text_weekly_ready' => 'Sygnał jest gotowy. Cotygodniowa kontrola ma teraz znaczenie, ponieważ plan opiera się już nie na zgadywaniu, lecz na rzeczywistych zachowaniach odwiedzających.',
    'ai_plan.signal_summary.watch_label' => 'Na co zwrócić szczególną uwagę',
    'ai_plan.signal_summary.watch_text_default' => 'Nie komplikuj aplikacji ani cotygodniowych działań bardziej, niż pozwalają na to obecne sygnały. Jasność przekazu jest ważniejsza niż jego szeroki zakres.',
    'ai_plan.signal_summary.watch_text_mobile' => 'Większość osób wyświetla Twoją stronę na telefonie. Pierwszy ekran, pierwsza wiadomość i pierwsze kliknięcie muszą być od razu zrozumiałe, bez konieczności przewijania i podejmowania wielu decyzji.',
    'ai_plan.signal_summary.watch_text_funnel_early' => 'Kroki sprzedażowe są już dostępne, ale sygnał wciąż jest słaby. Nie komplikuj ścieżki zbyt wcześnie, jeśli nie ma jeszcze pierwszych wartościowych kliknięć.',
    'ai_plan.signal_summary.watch_text_country' => 'Obecnie większość zainteresowania pochodzi z tego rynku: %s. Zadbaj o to, by wiadomość, przykład i oferta były zrozumiałe dla tych odbiorców.',
    'ai_plan.status_card_title' => 'Twój obecny status',
    'ai_plan.status_card_text_profile' => 'Uzupełnij profil, aby AI poznała twój cel, odbiorców i sposób pracy.',
    'ai_plan.status_card_text_signal' => 'Profil istnieje, ale sygnały wciąż się budują. Teraz najważniejsze jest uzyskanie jeszcze %s wartościowych kliknięć w Forever Webshop, aby tygodniowy plan miał solidne podstawy.',
    'ai_plan.status_card_text_weekly' => 'Sygnał jest gotowy. Najcenniejszym kolejnym krokiem jest wypełnienie cotygodniowego raportu, aby system mógł przygotować rzeczywisty plan na tydzień, a nie ogólną sugestię.',
    'ai_plan.status_card_text_plan_pending' => 'Istnieje cotygodniowe podsumowanie, ale plan nie został jeszcze zapisany. Następnym krokiem jest otwarcie aktualnego planu lub poczekanie na nowe cotygodniowe zgłoszenie, na podstawie którego powstanie nowy plan.',
    'ai_plan.status_card_text_execute' => 'Plan jest gotowy. Teraz skup się na jego realizacji bez rozpraszania się zbyt wieloma nowymi pomysłami, a następnie zapisz rzeczywisty rezultat.',
    'ai_plan.status_card_text_complete' => 'Ostatni cykl dobiegł końca. Teraz możesz wykorzystać jego wyniki, by z dużo jaśniejszym planem przystąpić do kolejnego cotygodniowego podsumowania.',
