    'index.presentation4.feature5' => 'Zgodność z GDPR, CCPA i PECR',
    'index.presentation5.header' => 'Zamień zainteresowanie w prawdziwy biznes',
    'index.presentation5.subheader' => 'Dzięki FCC Funnel łatwiej zbierasz kontakty, szybciej nawiązujesz dalszy kontakt i wyraźnie widzisz, co przynosi ci najwięcej zapytań, potencjalnych klientów i nowych członków zespołu.',
    'index.presentation5.feature1' => 'Łatwiejsze zbieranie kontaktów osób zainteresowanych',
    'index.presentation5.feature2' => 'Szybsza komunikacja i prostszy kontakt',
    'index.presentation5.feature3' => 'Lepsza widoczność i organizacja potencjalnych klientów',
    'index.presentation5.feature4' => 'Więcej możliwości rozwoju firmy i zespołu',
    'index.presentation6.header' => 'Asystenci AI do rekomendacji produktów',
    'index.presentation6.subheader' => 'Inteligentni asystenci AI pomagają ludziom szybko znajdować produkty Forever dla siebie, swoich rodzin i zwierząt, a tobie umożliwiają nawiązywanie większej liczby rozmów i stwarzają więcej możliwości sprzedaży.',
    'index.presentation6.feature1' => 'Rekomendacje produktów dla ludzi i zwierząt',
    'index.presentation6.feature2' => 'Łatwiejsza pierwsza rozmowa z potencjalnymi klientami',
    'index.presentation6.feature3' => 'Szybsze wskazówki dotyczące wyboru odpowiednich produktów',
    'index.presentation6.feature4' => 'Więcej zainteresowania, zapytań i możliwości sprzedaży',
    'index.tools.header' => '%s niezbędnych narzędzi',
    'index.tools.subheader' => 'Narzędzia internetowe. Szybkie, niezawodne i łatwe w obsłudze.',
    'index.documents' => 'Za pomocą naszych systemów AI wygenerowaliśmy też ponad <span class=\'text-primary-400\'>%1$s dokumentów</span>.',
    'index.images_subheader' => 'Oto nasze najnowsze wygenerowane obrazy.',
    'index.stats.links' => 'Inteligentne linki',
    'index.stats.qr_codes' => 'Dostęp przez NFC i kod QR',
    'index.stats.track_links' => 'Śledzone wizyty',
    'index.stats.note' => 'Wszystko można mierzyć. Sprawdź, w co klikają ludzie i skąd bierze się zainteresowanie.',
    'index.shortener_app_linking.header' => 'Adresy URL, które automatycznie otwierają aplikacje',
    'index.shortener_app_linking.subheader' => 'Krótkie linki, które automatycznie rozpoznają używaną aplikację i otwierają ją na urządzeniu mobilnym.',
    'index.domains.header' => 'Niestandardowe domeny',
    'index.domains.subheader' => 'Podłącz własną domenę lub skorzystaj z jednej z naszych gotowych.',
    'index.projects.header' => 'Projekty',
    'index.projects.subheader' => 'Najprostszy sposób na kategoryzowanie zarządzanych zasobów.',
    'index.file_links.header' => 'Linki do plików',
    'index.file_links.subheader' => 'Twórz dynamiczne, zaawansowane i możliwe do pobrania linki do plików.',
    'index.vcard_links.header' => 'Cyfrowa wizytówka',
    'index.vcard_links.subheader' => 'Twórz dynamiczne cyfrowe wizytówki, których użycie możesz śledzić i które można pobierać.',
    'index.splash_pages.header' => 'Strony docelowe',
    'index.splash_pages.subheader' => 'Używaj niestandardowych stron pośredniczących z odliczaniem czasu dla swoich linków.',
    'index.pixels.header' => 'Zaawansowana analityka i monitorowanie skuteczności',
    'index.pixels.subheader' => 'Wszystkie inteligentne linki i aplikacja Forever Card integrują się z wiodącymi platformami analitycznymi i reklamowymi.',
    'index.pixels.note' => 'Dane śledzenia pomagają partnerom zrozumieć, co działa: jakie treści wzbudzają zainteresowanie, skąd pochodzą odwiedzający i które kampanie przynoszą rezultaty. System obsługuje integrację z głównymi dostawcami pikseli i narzędzi śledzących.',
    'index.pricing.header' => 'Proste i przejrzyste ceny.',
    'index.testimonials.one.text' => 'Ta platforma całkowicie zmieniła sposób, w jaki zarządzamy naszymi procesami. Jest intuicyjna, szybka i co tydzień oszczędza naszemu zespołowi niezliczone godziny pracy.',
    'index.testimonials.one.attribute' => 'Redaktor, Writer\'s Weekly',
    'index.testimonials.two.text' => 'Na początku podchodziłem do tego sceptycznie, ale już po kilku dniach zauważyłem, o ile bardziej produktywny stał się nasz zespół. Zespół wsparcia również reaguje niezwykle szybko.',
    'index.partners.header' => 'Dlaczego partnerzy korzystają z Forever Card Club',
    'index.partners.subheader' => 'Ustrukturyzowany system cyfrowy do profesjonalnego i globalnego rozwijania biznesu Forever.',
    'index.partners.card1.title' => 'Jeden system, wszystko w jednym miejscu',
    'index.partners.card1.text' => 'Osobista aplikacja, inteligentne linki, edukacja, wsparcie AI i analityka, połączone w jeden cyfrowy ekosystem.',
    'index.partners.card2.title' => 'Globalne kierowanie bez komplikacji',
    'index.partners.card2.text' => 'Inteligentne linki automatycznie wykrywają kraj odwiedzającego i kierują go do oficjalnego sklepu internetowego Forever w jego regionie.',
    'index.partners.card3.title' => 'Profesjonalna obecność online i offline',
    'index.partners.card3.text' => 'Aplikacja osobista i karta NFC umożliwiają łatwe udostępnianie bez specjalistycznej wiedzy technicznej.',
    'index.partners.card4.title' => 'Przejrzysta struktura rozwoju',
    'index.partners.card4.text' => 'Ustrukturyzowany plan na 120 dni i edukacja krok po kroku pomagają partnerom budować stabilny i skalowalny system.',
    'index.faq.header' => 'Odpowiedzi na najczęściej zadawane pytania',
    'index.faq.one.question' => 'Jak pobrać aplikację Forever Card?',
    'index.faq.one.answer' => 'Otrzymujesz Forever Card App po zarejestrowaniu się jako partner biznesowy Forever, jeśli Twój sponsor należy do naszego zespołu. Po uzyskaniu dostępu przechodzisz prosty proces wdrożeniowy, który pokazuje, jak aktywować i skonfigurować swoją osobistą aplikację. Aplikacja to Twoja cyfrowa baza: wybierasz, które bloki mają być widoczne, na przykład wideo, produkty, doradca AI, kontakt i edukacja, a całość możesz skonfigurować bez umiejętności technicznych. Jeśli działasz również offline, otrzymujesz bezpłatną kartę NFC dostarczoną na Twój adres, która otwiera aplikację po szybkim dotknięciu lub zeskanowaniu.',
    'index.faq.two.question' => 'Jak działają zamawianie bez rejestracji i polecenia?',
    'index.faq.two.answer' => 'Forever Card Club korzysta z inteligentnych linków polecających, które można udostępniać na całym świecie. Gdy odwiedzający kliknie twój link lub wybierze produkt w aplikacji i kliknie „zamów”, system może automatycznie wykryć kraj tej osoby i przekierować ją do oficjalnego sklepu internetowego Forever w jej kraju. Twój link polecający jest wbudowany w link, dzięki czemu zakup może zostać przypisany tobie jako polecającemu partnerowi, zgodnie z oficjalnymi zasadami systemu. Ważne: Forever Card Club nie sprzedaje produktów. Wszystkie zakupy są realizowane w oficjalnym sklepie internetowym w kraju klienta.',
    'index.faq.three.question' => 'Co otrzymuję jako członek zespołu?',
    'index.faq.three.answer' => 'Jako członek zespołu otrzymujesz kompletny system do budowania biznesu Forever online, w tym: osobistą aplikację Forever Card App, w której znajdziesz wszystkie narzędzia i treści, inteligentne linki polecające kierujące klientów z różnych krajów do oficjalnego sklepu internetowego, doradcę AI w aplikacji, który pomaga w wyborze produktów i udziela informacji, szkolenia krok po kroku, które uczą korzystania z systemu i budowania biznesu online, spersonalizowany plan na 120 dni dostosowany do twoich nawyków i celów, analitykę pokazującą, co klikają inni, skąd pochodzą i co sprawdza się najlepiej, a także bezpłatną kartę NFC dostarczoną na twój adres, którą możesz wykorzystać w kontaktach bezpośrednich. Otrzymujesz również wsparcie społeczności, na przykład grupy WhatsApp i jasne wytyczne, które pomogą ci działać konsekwentnie i budować długofalowe wyniki.',
    'index.faq.four.question' => 'Jak działa plan na 120 dni?',
    'index.faq.four.answer' => 'Plan na 120 dni to ustrukturyzowany program, który prowadzi partnerów od początkowej konfiguracji, przez budowanie nawyków, aż po regularną komunikację online, rekomendacje oraz rozwój zespołu i bazy klientów. To nie jest uniwersalny plik PDF. Plan jest dopasowywany do danej osoby, jej dostępnego czasu, stylu komunikacji, poziomu doświadczenia i celów. Zawiera jasne wskazówki dotyczące konfiguracji aplikacji, korzystania z inteligentnych linków, prezentowania informacji online oraz budowania powtarzalnego systemu, który można powielić w przyszłym zespole.',
    'index.faq.five.question' => 'Co robi doradca AI w aplikacji?',
    'index.faq.five.answer' => 'Doradca AI ułatwia odwiedzającym korzystanie z informacji. Na podstawie ich pytań może zaproponować przydatne informacje i produkty, a następnie pokierować ich do kolejnego kroku, na przykład zdobycia dodatkowych informacji, kontaktu lub złożenia zamówienia. Jeśli odwiedzający zdecyduje się na zakup, doradca AI może przekierować go do oficjalnego sklepu internetowego za pomocą inteligentnych linków powiązanych z poleceniem partnera. Partnerzy nie muszą dzięki temu wielokrotnie przekazywać podstawowych informacji, a komunikacja pozostaje jasna i spójna.',
    'index.faq.contact_note' => 'Jeśli chcesz uzyskać dostęp lub masz pytanie, skontaktuj się przez %s.',
    'index.faq.contact_link' => 'Strona kontaktowa',
