    'links.short_links.guide_text' => 'Utwórz krótki link w kilka sekund, a następnie użyj opcji Edytuj, aby określić jego działanie. Ten widok przeprowadzi Cię teraz przez tworzenie linków, zarządzanie listą, statystyki i zaawansowane ustawienia przekierowań, aby umożliwić Ci swobodne korzystanie z każdej opcji.',
