    'links.short_links.guide_card_1_text' => 'Zacznij od docelowego adresu URL i, jeśli chcesz, ustaw własny alias. Jeśli pole pozostanie puste, system wygeneruje alias automatycznie.',
    'links.short_links.guide_card_2_title' => 'Edytuj z konkretnym celem',
    'links.short_links.guide_card_2_text' => 'Otwórz Edytuj, aby zarządzać śledzeniem, tymczasowymi regułami, łączeniem z aplikacją, ochroną hasłem, maskowaniem linków, kierowaniem do odbiorców i innymi ustawieniami przekierowań.',
    'links.short_links.guide_card_3_title' => 'Zarządzaj na dużą skalę',
    'links.short_links.guide_card_3_text' => 'Korzystaj z importu zbiorczego, filtrów, kopiowania, kodów QR, duplikowania, resetowania i przełączników statusu, aby uporządkować większą bibliotekę linków.',
    'links.short_links.guide_card_4_title' => 'Sprawdzaj, co działa',
