    'links.short_links.empty_text' => 'Zacznij od przycisku Skrócony URL, a następnie otwórz Edytuj, aby uzyskać dostęp do opcji śledzenia, harmonogramu, grupy docelowej, zabezpieczeń i brandingu.',
    'links.short_links.tour.create_title' => 'Utwórz krótki link',
    'links.short_links.tour.create_text' => 'To najszybszy sposób na dodanie nowego krótkiego linku. Potrzebujesz tylko docelowego adresu URL. Jeśli chcesz, możesz też ustawić własny, łatwy do zapamiętania alias.',
    'links.short_links.tour.bulk_title' => 'Importuj lub twórz zbiorczo',
    'links.short_links.tour.bulk_text' => 'Gdy masz już przygotowanych wiele miejsc docelowych, narzędzia zbiorcze pomagają szybciej tworzyć wiele krótkich linków i lepiej organizować prace związane z ich uruchomieniem.',
    'links.short_links.tour.list_title' => 'Wszystko jest widoczne w jednym miejscu',
    'links.short_links.tour.list_text' => 'Ta lista stanie się centrum zarządzania krótkimi linkami. Nazwy, podglądy stron docelowych, statystyki, daty, statusy, opcje kopiowania i szybkie działania będą czytelnie zebrane w jednym miejscu.',
    'links.short_links.tour.row_title' => 'Każdy wiersz to aktywny element przekierowujący',
    'links.short_links.tour.row_text' => 'Pojedynczy krótki link może oferować znacznie więcej niż zwykłe przekierowanie. W sekcji Edytuj możesz dodać śledzenie UTM, harmonogramy, reguły wygasania, maskowanie linku, targetowanie i inne zaawansowane funkcje.',
    'links.short_links.tour.actions_title' => 'Edytuj, mierz, duplikuj, resetuj',
    'links.short_links.tour.actions_text' => 'Za pomocą menu działań możesz otworzyć opcję Edytuj, wyświetlić statystyki, utworzyć kod QR, zduplikować, zresetować dane lub usunąć. Pełny samouczek jest kontynuowany na ekranie Edytuj.',
