    'qr_codes.breadcrumb' => 'Kody QR',
    'qr_codes.header' => 'Kody QR',
    'qr_codes.subheader' => 'Z łatwością twórz własne kody QR i zapisuj je na później.',
    'qr_codes.page_intro' => 'Twórz samodzielne kody QR do druku, udostępniania offline, wydarzeń, produktów, Wi-Fi, przekazywania kontaktów i wielu innych zastosowań. Każda aplikacja Forever Card może też utworzyć własny bezpośredni kod QR, a ta sekcja daje ci osobną przestrzeń do tworzenia i edytowania kodów w jednym miejscu.',
    'qr_codes.guide_title' => 'Osobna przestrzeń QR do materiałów drukowanych, udostępniania offline i kontrolowanych zastosowań',
    'qr_codes.guide_text' => 'Ta sekcja kodów QR służy do zarządzania samodzielnymi kodami QR poza konkretnym ekranem aplikacji. Użyj jej, gdy potrzebujesz kodów QR do druku, wielokrotnego użytku kodów kampanii, punktów dostępu do wydarzeń lub produktów albo kodu QR, który wymaga własnego stylu i procesu eksportu.',
    'qr_codes.guide_card_1_title' => 'Oddzielnie od kodu QR aplikacji',
    'qr_codes.guide_card_1_text' => 'Każda aplikacja Forever Card może wygenerować własny bezpośredni kod QR. Tutaj możesz jednak utworzyć całkowicie osobne kody QR dla innych stron docelowych, linków, materiałów i kampanii.',
    'qr_codes.guide_card_2_title' => 'Przygotowane do druku i użytku offline',
    'qr_codes.guide_card_2_text' => 'Te kody QR świetnie sprawdzają się na ulotkach, wizytówkach, plakatach, kartach produktów, stoiskach na wydarzeniach i opakowaniach, a także do udostępniania na żywo, gdy ktoś może zeskanować kod zamiast wpisywać adres.',
    'qr_codes.guide_card_3_title' => 'Dostosuj i wyeksportuj poprawnie',
    'qr_codes.guide_card_3_text' => 'Dostosuj typ i styl kodu QR, kolory, ramki, logo, branding oraz format pliku, aby gotowy kod pasował do miejsca, w którym będzie używany.',
    'qr_codes.guide_card_4_title' => 'Edytuj i wykorzystaj ponownie później',
    'qr_codes.guide_card_4_text' => 'Po utworzeniu każdy kod QR pozostaje dostępny do pobrania, wydrukowania, duplikowania i późniejszego dostosowania, bez konieczności tworzenia go od nowa.',
    'qr_codes.empty_title' => 'Utwórz swój pierwszy kod QR',
    'qr_codes.empty_text' => 'Zacznij od samodzielnego kodu QR prowadzącego do linku, aplikacji, kontaktu, wydarzenia lub materiału drukowanego. Po utworzeniu możesz wrócić, aby edytować styl, ramkę, elementy marki i format eksportu.',
    'qr_codes.tour.create_title' => 'Utwórz samodzielny kod QR',
    'qr_codes.tour.create_text' => 'Użyj tego przycisku, gdy chcesz utworzyć kod QR, który będzie działać poza pojedynczą stroną Forever Card App. Świetnie sprawdzi się w kampaniach, materiałach drukowanych, na wydarzeniach i do wielokrotnego udostępniania offline.',
    'qr_codes.tour.guide_title' => 'Dowiedz się, kiedy ta sekcja jest właściwym miejscem',
    'qr_codes.tour.guide_text' => 'Ten przewodnik wyjaśnia różnicę między kodami QR przeznaczonymi do aplikacji a samodzielnymi materiałami z kodem QR. Jego celem jest pomoc w wyborze odpowiedniego procesu przed utworzeniem lub edycją.',
    'qr_codes.tour.list_title' => 'Tutaj twoja biblioteka kodów QR pozostaje uporządkowana',
    'qr_codes.tour.list_text' => 'Ta lista staje się centrum zarządzania wszystkimi samodzielnymi kodami QR. Znajdziesz tu podgląd, nazwę, typ, powiązany projekt, opcje eksportu i dostęp do edycji.',
    'qr_codes.tour.row_title' => 'Każdy wiersz to zasób QR wielokrotnego użytku',
    'qr_codes.tour.row_text' => 'Kod QR może zawierać adres URL, link do aplikacji, wydarzenie, dane dostępu do Wi-Fi, wizytówkę vCard, prośbę o płatność lub wiele innych rodzajów treści otwieranych po zeskanowaniu. Możesz z czasem nadal ulepszać ten sam zasób.',
