    'qr_code_update.title' => 'Edytuj kod QR',
    'qr_code_update.header' => 'Edytuj kod QR',
    'qr_codes.editor.hero_title' => 'Zmień zwykły kod QR w punkt dostępu, który można wielokrotnie wykorzystywać, łączący świat offline z cyfrowym',
    'qr_codes.editor.hero_text' => 'Ten edytor pozwala przygotować kod QR do praktycznego zastosowania, opatrzyć go marką i dostosować do konkretnych potrzeb. Każda aplikacja Forever Card może wygenerować własny kod QR, ale tutaj możesz osobno tworzyć i ulepszać kody QR przeznaczone do druku, kampanii, wydarzeń, ścieżek produktowych, udostępniania kontaktów i wielu innych sytuacji, w których ktoś może zeskanować kod.',
    'qr_codes.editor.hero_card_1_title' => 'Wybierz wynik skanowania',
    'qr_codes.editor.hero_card_1_text' => 'Zdecyduj, czy kod QR ma otwierać adres URL, kartę kontaktową, płatność, połączenie Wi-Fi, wersję roboczą wiadomości, wydarzenie, lokalizację czy inną obsługiwaną funkcję.',
    'qr_codes.editor.hero_card_2_title' => 'Dopasuj projekt do kontekstu',
    'qr_codes.editor.hero_card_2_text' => 'Dostosuj styl, kolory, ramkę, elementy marki i opcjonalne logo, aby kod QR pasował do ulotki, wizytówki, karty produktu, prezentacji lub materiałów na wydarzenie.',
    'qr_codes.editor.hero_card_3_title' => 'Podgląd przed drukowaniem',
    'qr_codes.editor.hero_card_3_text' => 'Skorzystaj z podglądu na żywo, sprawdzania czytelności i opcji pobierania, aby przetestować kod QR, zanim go wydrukujesz lub udostępnisz publicznie.',
    'qr_codes.editor.hero_card_4_title' => 'Wykorzystuj ponownie zamiast tworzyć od nowa',
    'qr_codes.editor.hero_card_4_text' => 'Gdy kod QR działa już dobrze, edytuj go, duplikuj lub eksportuj na potrzeby nowych kampanii zamiast za każdym razem zaczynać od początku.',
    'qr_codes.editor.tour.intro_title' => 'Przegląd edytora QR',
    'qr_codes.editor.tour.intro_text' => 'Ta strona pomaga utworzyć lub dopracować samodzielny kod QR, który można wydrukować, udostępniać, eksportować i ponownie wykorzystywać w wielu sytuacjach.',
    'qr_codes.editor.tour.type_title' => 'Wybierz, co ma zrobić skan',
    'qr_codes.editor.tour.type_text' => 'Typ kodu QR określa, co zobaczy osoba, która go zeskanuje: otwarcie linku, zapisanie danych kontaktowych, uruchomienie wiadomości, połączenie z Wi-Fi, wyświetlenie prośby o płatność i inne możliwości.',
    'qr_codes.editor.tour.basics_title' => 'Zacznij od imienia i najważniejszych danych',
    'qr_codes.editor.tour.basics_text' => 'Nadaj kodowi QR jasną nazwę wewnętrzną i uzupełnij najważniejsze pola. To podstawowa zawartość, która zostanie umieszczona w kodzie.',
    'qr_codes.editor.tour.style_title' => 'Nadaj kształt samemu wzorowi QR',
    'qr_codes.editor.tour.style_text' => 'Styl określa kształt modułów i znaczników narożnych kodu QR. Przydaje się, gdy kod QR ma wizualnie pasować do marki, kampanii lub materiału drukowanego.',
    'qr_codes.editor.tour.colors_title' => 'Kontroluj kontrast i czytelność podczas szybkiego przeglądania',
    'qr_codes.editor.tour.colors_text' => 'Kolory to nie tylko kwestia estetyki. Dobry kontrast ma kluczowe znaczenie dla niezawodnego skanowania, zwłaszcza gdy kod QR będzie drukowany lub oglądany przy nieidealnym oświetleniu.',
    'qr_codes.editor.tour.frame_title' => 'Dodaj kontekst wokół kodu QR',
    'qr_codes.editor.tour.frame_text' => 'Ramki pomagają nadać kodowi QR przemyślany wygląd. Mogą też zawierać wezwanie do działania lub etykietę, aby od razu było jasne, dlaczego warto go zeskanować.',
    'qr_codes.editor.tour.branding_title' => 'Ostrożnie dodawaj logo i elementy identyfikacji marki',
    'qr_codes.editor.tour.branding_text' => 'Opcje brandingu pozwalają umieszczać logo i obrazy w kompozycji kodu QR, ale należy je dokładnie przetestować, aby kod pozostał czytelny.',
    'qr_codes.editor.tour.options_title' => 'Zakończ konfigurację techniczną',
    'qr_codes.editor.tour.options_text' => 'Rozmiar, margines, kodowanie, korekcja błędów i organizacja projektu pomagają zapewnić prawidłowe działanie kodu QR podczas eksportu i w zastosowaniach produkcyjnych.',
    'qr_codes.editor.tour.preview_title' => 'Obejrzyj końcowy kod QR na żywo',
    'qr_codes.editor.tour.preview_text' => 'W podglądzie możesz sprawdzić, czy kod QR jest wyraźny i można go zeskanować, zanim go pobierzesz, wydrukujesz lub udostępnisz.',
    'qr_codes.editor.tour.download_title' => 'Przygotuj materiały do wydruku lub dostarczenia',
    'qr_codes.editor.tour.download_text' => 'Eksportuj do SVG, PNG, JPG lub WEBP, zależnie od tego, czy potrzebujesz jakości do druku, przezroczystości, materiału do prezentacji czy szybkiego udostępnienia.',
    'qr_codes.editor.tour.save_title' => 'Zapisz, przetestuj, a następnie opublikuj',
    'qr_codes.editor.tour.save_text' => 'Po zapisaniu zeskanuj kod QR na co najmniej jednym telefonie, zanim zaczniesz go używać publicznie. Jest to szczególnie ważne w przypadku ramek, gradientów, logo lub materiałów drukowanych.',
    'biolink_block_delete.header' => 'Usuń blok',
    'biolink_block_delete.subheader' => 'Wszystkie dane powiązane z blokiem FCC zostaną całkowicie usunięte. Tej czynności nie można cofnąć.',
    'biolink_block_delete.success_message' => 'Usunięcie bloku FCC powiodło się.',
    'biolink_block.title' => 'Blok FCC',
