    'link.header.subheader' => 'Aplikacja Forever Card: %s',
    'link.header.short_link_subheader' => 'Ustawienia krótkiego linku: %s',
    'link.short_editor.hero_title' => 'Zamień krótki adres URL w kontrolowane przekierowanie',
    'link.short_editor.hero_text' => 'Ten edytor pozwala nadać krótkiemu linkowi strategiczne znaczenie. Oprócz aliasu i miejsca docelowego możesz dodać harmonogram, śledzenie UTM, ochronę hasłem, łączenie z aplikacją, maskowanie linku, kierowanie według urządzenia lub lokalizacji, obsługę HTTP i inne zaawansowane opcje.',
    'link.short_editor.hero_card_1_title' => 'Zacznij od podstaw',
    'link.short_editor.hero_card_1_text' => 'Określ docelowy adres URL, wybierz krótki alias i zdecyduj, z jakiej domeny ma korzystać krótki link.',
    'link.short_editor.hero_card_2_title' => 'Ustal, jak ma działać',
    'link.short_editor.hero_card_2_text' => 'Określ, kiedy link działa, dokąd przekierowuje, co dzieje się po wygaśnięciu oraz czy ma przekazywać dalej parametry zapytania.',
    'link.short_editor.hero_card_3_title' => 'Śledź i personalizuj',
    'link.short_editor.hero_card_3_text' => 'Dodaj tagi UTM, piksele, metadane maskujące i linkowanie do aplikacji, aby każde kliknięcie zawierało potrzebny kontekst.',
    'link.short_editor.hero_card_4_title' => 'Chroń i optymalizuj',
    'link.short_editor.hero_card_4_text' => 'Dopasuj każdą kampanię i grupę odbiorców za pomocą haseł, ostrzeżeń o wrażliwej treści, kierowania do odbiorców i kodów przekierowań.',
    'link.short_editor.form_title' => 'Co możesz skonfigurować w krótkim linku',
    'link.short_editor.form_text' => 'Otwórz tylko potrzebne sekcje albo przejdź przez samouczek krok po kroku. Każda z poniższych grup odpowiada za jeden element działania krótkiego linku, od prostych przekierowań po zaawansowaną logikę kampanii.',
    'link.short_editor.card_1_title' => 'Z myślą o udanych premierach',
    'link.short_editor.card_1_text' => 'Ustaw miejsce docelowe, alias, domenę i kod przekierowania, aby link działał dokładnie tak, jak chcesz, już od pierwszego udostępnienia.',
    'link.short_editor.card_2_title' => 'Do kampanii i raportowania',
    'link.short_editor.card_2_text' => 'Dodaj wartości UTM, piksele, raporty i projekty, aby prawidłowo mierzyć ruch i grupować go.',
    'link.short_editor.card_3_title' => 'W przypadku zaawansowanego działania',
    'link.short_editor.card_3_text' => 'Ustal dostępność, zasady wygasania i grupę odbiorców, zabezpiecz dostęp lub w razie potrzeby ukryj stronę docelową.',
    'link.short_editor.tour.intro_title' => 'Przegląd edytora krótkich linków',
    'link.short_editor.tour.intro_text' => 'Ta strona zawiera wszystkie zaawansowane opcje jednego krótkiego linku. Jej cel jest prosty: pomóc Ci zrozumieć, co zmienia każde ustawienie, zanim je zapiszesz.',
    'link.short_editor.tour.basics_title' => 'Najpierw podstawy',
    'link.short_editor.tour.basics_text' => 'Tutaj określasz, dokąd prowadzi krótki link, jakiego aliasu używa i w jakiej domenie ma działać. To podstawowe ustawienia przekierowania.',
    'link.short_editor.tour.app_linking_title' => 'Otwieraj aplikacje mobilne bezpośrednio',
    'link.short_editor.tour.app_linking_text' => 'Linkowanie aplikacji pomaga otwierać obsługiwane odnośniki do treści mobilnych w natywnej aplikacji, a nie tylko w przeglądarce, co może poprawić komfort korzystania z telefonu.',
    'link.short_editor.tour.temporary_title' => 'Ustaw zasady dotyczące czasu i wygaśnięcia',
    'link.short_editor.tour.temporary_text' => 'Użyj tej sekcji, aby zaplanować dostępność, ograniczyć liczbę kliknięć lub określić, dokąd mają trafiać użytkownicy po wygaśnięciu linku. Ta funkcja świetnie sprawdza się przy promocjach, premierach i kampaniach ograniczonych czasowo.',
    'link.short_editor.tour.utm_title' => 'Dodaj kontekst analityczny',
    'link.short_editor.tour.utm_text' => 'Parametry UTM pomagają narzędziom analitycznym rozpoznawać źródło ruchu, medium i kampanię. To jedno z najlepszych miejsc do ujednolicenia nazewnictwa kampanii.',
    'link.short_editor.tour.protection_title' => 'W razie potrzeby zabezpiecz dostęp',
    'link.short_editor.tour.protection_text' => 'Ostrzeżenia dotyczące haseł i poufnych treści są przydatne, gdy link nie powinien być w pełni otwarty lub gdy użytkownicy potrzebują kontekstu, zanim przejdą dalej.',
    'link.short_editor.tour.targeting_title' => 'Kieruj różne grupy odbiorców do różnych miejsc docelowych',
    'link.short_editor.tour.targeting_text' => 'Kierowanie pozwala dostosować działanie jednego krótkiego linku do kraju, miasta, urządzenia, systemu operacyjnego, języka przeglądarki lub reguł rotacji. To przydatne rozwiązanie w kampaniach kierowanych do różnych segmentów.',
    'link.short_editor.tour.cloaking_title' => 'Kontroluj podgląd widoczny dla innych',
    'link.short_editor.tour.cloaking_text' => 'Maskowanie zmienia tytuł, opis, obraz i inne metadane wyświetlane przed przekierowaniem. Przydaje się, gdy podgląd udostępnianego linku powinien pasować do przekazu kampanii.',
    'link.short_editor.tour.http_title' => 'Wybierz typ przekierowania',
    'link.short_editor.tour.http_text' => 'Kody 301, 302, 307 i 308 nie są identyczne. Ta sekcja określa, czy przekierowanie jest uznawane za stałe czy tymczasowe oraz jak przeglądarki powinny je obsługiwać.',
    'link.short_editor.tour.advanced_title' => 'Zakończ, korzystając z zaawansowanych ustawień',
    'link.short_editor.tour.advanced_text' => 'Znajdziesz tu projekty, strony powitalne, powiadomienia, przekierowywanie zapytań i powiązane opcje, dzięki którym krótki link może być częścią szerszego procesu.',
    'link.short_editor.tour.save_title' => 'Zapisz i przetestuj',
    'link.short_editor.tour.save_text' => 'Po zapisaniu przetestuj krótki link na komputerze i urządzeniu mobilnym. Sprawdź też statystyki, aby potwierdzić, że przekierowania, przypisywanie źródeł i targetowanie działają zgodnie z oczekiwaniami.',
