    'fcc.page.semantics_heading' => 'Czym jest Forever Card Club (FCC)?',
    'fcc.page.semantics_summary' => 'Forever Card Club (FCC) to kompleksowy cyfrowy system biznesowy dla partnerów Forever Living Products. FCC łączy osobistą aplikację, inteligentne linki polecające, asystentów AI do produktów, mechanizmy lejka sprzedażowego, materiały edukacyjne, analitykę oraz fizyczną kartę NFC w jeden sposób prowadzenia biznesu.',
    'fcc.page.semantics_fact_1' => 'Forever Card Club nie jest oficjalną witryną ani sklepem Forever Living Products, lecz niezależnym systemem dla partnerów.',
