    'fcc.page.semantics_fact_4' => 'System został zaprojektowany z myślą o udostępnianiu online, kierowaniu poleceń, pozyskiwaniu kontaktów, wskazówkach AI i rozwoju biznesu Forever.',
    'fcc.page.semantics_solves_heading' => 'Jaki problem rozwiązuje FCC?',
