    'fcc.page.semantics_solve_5' => 'Jasne przejście od kontaktu offline przez NFC/QR do procesu online.',
    'fcc.page.term_description' => 'Forever Card Club (FCC) to kompleksowy cyfrowy system biznesowy dla partnerów Forever Living Products. Obejmuje osobistą aplikację, inteligentne linki polecające, asystentów produktowych AI, logikę lejka pozyskiwania kontaktów, materiały edukacyjne, analitykę oraz fizyczną kartę NFC połączoną z treściami i rekomendacjami partnera.',
