    'fcc_ai.platform.title' => 'Przegląd platformy',
    'fcc_ai.platform.note_admin' => 'Szczegóły techniczne są nadal dostępne poniżej w rozwijanych sekcjach, dzięki czemu główny ekran pozostaje przejrzysty.',
    'fcc_ai.platform.note_user' => 'Sprawdź w jednym miejscu, jak włączono AI w aplikacji, jak działa Coach oraz gdzie śledzone są rozmowy i potencjalni klienci.',
    'fcc_ai.platform.list.app_blocks_title' => 'Bloki AI w aplikacji',
    'fcc_ai.platform.list.app_blocks_text' => 'Publiczna funkcja AI jest włączana przez dodanie bloku AI w ustawieniach aplikacji FCC. Po dodaniu AI pojawi się w tej aplikacji.',
    'fcc_ai.platform.list.coach_title' => 'FCC Coach',
    'fcc_ai.platform.list.coach_text' => 'Coach jest zawsze dostępny w FCC, powiązany z planem rozwoju i stworzony, aby wspierać cię w korzystaniu z platformy, mediach społecznościowych, komunikacji i rozwijaniu biznesu.',
    'fcc_ai.platform.list.single_ai_title' => 'Jedna AI na aplikację',
    'fcc_ai.platform.list.single_ai_text' => 'W jednej aplikacji FCC może być aktywny tylko jeden doradca AI. Jeśli dodano już jeden blok AI, próba dodania kolejnego spowoduje wyświetlenie ostrzeżenia.',
    'fcc_ai.platform.list.leads_title' => 'Leady AI',
    'fcc_ai.platform.list.leads_text' => 'Leady AI są zapisywane w istniejącej skrzynce odbiorczej /data i łączone z powiązaną rozmową.',
    'fcc_ai.guide.title' => 'Jak korzystać z FCC AI',
    'fcc_ai.guide.subtitle' => 'Te krótkie poradniki wyjaśniają, co potrafi każda AI i jak najlepiej wykorzystać ją w codziennej pracy.',
    'fcc_ai.guide.coach.title' => 'AI Coach',
    'fcc_ai.guide.coach.summary' => 'Wsparcie w pracy z FCC, realizacji planu rozwoju i podejmowaniu kolejnych praktycznych kroków.',
    'fcc_ai.guide.coach.intro' => 'FCC Coach to Twój osobisty asystent na platformie. Jest połączony z Twoim planem rozwoju i pomaga Ci wybrać najbardziej przydatny kolejny krok.',
    'fcc_ai.guide.coach.point_1' => 'Może pomóc w planowaniu, ustalaniu priorytetów, skupieniu się i wyborze kolejnego kroku, gdy nie wiesz, co robić dalej lub czujesz, że utknąłeś.',
    'fcc_ai.guide.coach.point_2' => 'Podsuwa pomysły na treści, komunikację, media społecznościowe i codzienne działania wspierające rozwój firmy.',
    'fcc_ai.guide.coach.point_3' => 'Prowadzi cię przez Twój Plan Rozwoju i podpowiada, co zrobić w zależności od tego, czego potrzebujesz w danym momencie.',
    'fcc_ai.guide.coach.tip' => 'Najwięcej zyskasz, jeśli jasno napiszesz, na jakim etapie jesteś, co chcesz osiągnąć i jakiej pomocy teraz potrzebujesz.',
    'fcc_ai.guide.sales.title' => 'AI do sprzedaży, rekomendacji i współpracy biznesowej',
    'fcc_ai.guide.sales.summary' => 'Publiczna AI, która poleca produkty, korzysta z bloga i rozpoznaje zainteresowanie współpracą.',
    'fcc_ai.guide.sales.intro' => 'To AI rozmawia z użytkownikami odwiedzającymi Twoją aplikację FCC, pomaga im dobrać produkty dla ludzi lub zwierząt i kieruje ich do kolejnego kroku, zakupu lub współpracy biznesowej.',
    'fcc_ai.guide.sales.point_1' => 'Odpowiada na pytania, poleca produkty i może przekierować odwiedzających do odpowiedniego artykułu na blogu FCC, który zawiera bardziej szczegółowe wyjaśnienia.',
    'fcc_ai.guide.sales.point_2' => 'Towarzyszy odwiedzającemu przez całą ścieżkę, od pierwszego pytania po dalszą rozmowę na blogu lub przejście do kontaktu.',
    'fcc_ai.guide.sales.point_3' => 'Może zbierać dane od zainteresowanych osób i zapisywać kontakty, aby partner mógł się z nimi skontaktować.',
    'fcc_ai.guide.sales.point_4' => 'Może rozpoznać zainteresowanie biznesem i wspierać sponsoring, kierując odwiedzającego do kolejnego wartościowego kroku.',
    'fcc_ai.guide.sales.tip' => 'Najlepiej sprawdza się jasny przekaz, konkretne zasady i dobrze wyjaśniona logika rekomendacji.',
    'fcc_ai.guide.settings.title' => 'Ustawienia doradcy',
    'fcc_ai.guide.settings.summary' => 'Tutaj określasz, jak publiczna AI się wypowiada, odpowiada i na co zwraca uwagę.',
    'fcc_ai.guide.settings.intro' => 'W ustawieniach publicznego doradcy AI możesz dostosować sposób komunikacji, aby pasował do Twojego stylu, odbiorców i celu aplikacji.',
    'fcc_ai.guide.settings.point_1' => 'Nazwa i język asystenta określają, jak AI się przedstawia i jakim językiem naturalnie się posługuje.',
    'fcc_ai.guide.settings.point_2' => 'Ton wypowiedzi pozwala AI brzmieć w sposób doradczy, wspierający, przyjazny lub bardziej bezpośredni, zależnie od tego, czego chcesz.',
    'fcc_ai.guide.settings.point_3' => 'W instrukcjach dotyczących persony opisz preferowany styl: cieplejsze podejście, krótsze odpowiedzi, więcej pytań, większe skupienie na produktach lub na biznesie.',
    'fcc_ai.guide.settings.point_4' => 'W zasadach i ograniczeniach określ, o czym AI ma zawsze wspominać, czego ma unikać i jak formułować rekomendacje.',
    'fcc_ai.guide.settings.tip' => 'Najlepiej sprawdzają się krótkie i konkretne wskazówki. Napisz je tak, jakbyś wyjaśniał, jak dobry doradca powinien rozmawiać z gościem.',
    'fcc_ai.guide.inbox.title' => 'Skrzynka odbiorcza AI z ostatnich 30 dni',
    'fcc_ai.guide.inbox.summary' => 'Miejsce do śledzenia rozmów i leadów oraz doskonalenia komunikacji czatu AI.',
    'fcc_ai.guide.inbox.intro' => 'Skrzynka AI pokazuje, jak asystent rozmawiał z prawdziwymi użytkownikami. To najlepsze miejsce do monitorowania jakości i ciągłego ulepszania asystenta.',
    'fcc_ai.guide.inbox.point_1' => 'Otwórz rozmowy i sprawdź, gdzie AI odpowiedziała dobrze, a gdzie odpowiedź mogłaby być jaśniejsza lub bardziej przydatna.',
    'fcc_ai.guide.inbox.point_2' => 'Obserwuj, które pytania często się powtarzają, aby ulepszać ton wypowiedzi, instrukcje dotyczące persony i zasady.',
    'fcc_ai.guide.inbox.point_3' => 'Jeśli użytkownicy nadal proszą o dodatkowe wyjaśnienia, skróć odpowiedzi, dodaj jaśniejsze instrukcje lub lepiej kieruj ich do bloga albo do kontaktu.',
    'fcc_ai.guide.inbox.point_4' => 'Śledź potencjalnych klientów pozyskanych przez AI i wykorzystaj te informacje, aby sprawdzić, w czym czat najbardziej pomaga w sprzedaży i pozyskiwaniu współpracowników.',
    'fcc_ai.guide.inbox.tip' => 'Jeśli zauważysz ten sam problem więcej niż raz, od razu zmień ustawienia doradcy. Niewielkie zmiany tonu i zasad często przynoszą dużą poprawę.',
